:root {
  /* 主色阶 */
  --c-primary-50:  #F1FAF5;
  --c-primary-100: #E8F6EE;
  --c-primary-200: #C9EAD8;
  --c-primary-300: #9BD8B5;
  --c-primary-400: #63BD8A;
  --c-primary-500: #2E9E5B;   /* 品牌亮色：图形用 */
  --c-primary-600: #24814A;   /* 交互主色：文字/按钮用 */
  --c-primary-700: #1C663A;
  --c-primary-800: #164E2D;
  --c-primary-900: #0E3520;

  /* 语义 */
  --c-success: #2E9E5B;  --c-success-bg: #E8F6EE;  --c-success-text: #1C663A;
  --c-warning: #F2A93B;  --c-warning-bg: #FEF6E7;  --c-warning-text: #96590A;
  --c-error:   #D6453E;  --c-error-bg:   #FDECEB;  --c-error-text:   #992620;
  --c-info:    #3A7BD5;  --c-info-bg:    #EAF2FD;  --c-info-text:    #23528F;

/* 中性 */
  --c-bg-page: #F7FAF8;
  --c-bg-subtle: #EFF3F0;
  --c-border: #E2E8E4;
  --c-border-split: #EFF3F0;
  --c-text-title: #1C2620;
  --c-text-body: #2E3A33;
  --c-text-sub: #6B7A72;
  --c-text-placeholder: #9AA8A0;

  /* 圆角 / 阴影 */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --shadow-sm: 0 1px 2px rgba(16, 38, 26, 0.04);
  --shadow-md: 0 4px 12px rgba(16, 38, 26, 0.06);
  --shadow-lg: 0 8px 24px rgba(16, 38, 26, 0.08);
}
